import { fulfillVerifiedPurchase } from './fulfillment.mjs';

const validDiscord = id => typeof id === 'string' && /^\d{15,22}$/.test(id);
const validPurchase = id => typeof id === 'string' && /^[a-f0-9]{24}$/.test(id);
const validOrder = id => typeof id === 'string' && /^[A-Z0-9]{8,40}$/.test(id);

// The caller must obtain discordId from a verified website session, never from
// request JSON. purchaseId must be generated by the server with 12 random bytes.
export async function createCheckout(db, paypal, { purchaseId, discordId }) {
  if (!validPurchase(purchaseId) || !validDiscord(discordId)) throw new Error('Invalid purchase');
  await db.prepare(`INSERT OR IGNORE INTO paypal_purchases (id,discord_id,status,created_at)
    VALUES (?,?,'created',?)`).bind(purchaseId, discordId, Math.floor(Date.now()/1000)).run();
  const row = await db.prepare('SELECT * FROM paypal_purchases WHERE id=? AND discord_id=?').bind(purchaseId, discordId).first();
  if (!row || row.status !== 'created') throw new Error('Purchase not available');
  if (row.paypal_order_id) return { purchaseId, orderId: row.paypal_order_id };
  const created = await paypal.createOrder(purchaseId);
  if (!validOrder(created?.id)) throw new Error('Invalid PayPal order response');
  const linked = await db.prepare(`UPDATE paypal_purchases SET paypal_order_id=?
    WHERE id=? AND discord_id=? AND status='created' AND paypal_order_id IS NULL RETURNING paypal_order_id`)
    .bind(created.id, purchaseId, discordId).first();
  if (!linked) {
    const existing = await db.prepare('SELECT paypal_order_id FROM paypal_purchases WHERE id=? AND discord_id=?')
      .bind(purchaseId, discordId).first();
    if (existing?.paypal_order_id !== created.id) throw new Error('Order link conflict');
  }
  return { purchaseId, orderId: created.id };
}

export async function completeCheckout(db, paypal, secret, merchantId, { purchaseId, discordId }) {
  if (!validPurchase(purchaseId) || !validDiscord(discordId)) throw new Error('Invalid purchase');
  const row = await db.prepare('SELECT * FROM paypal_purchases WHERE id=? AND discord_id=?').bind(purchaseId, discordId).first();
  if (!row || !validOrder(row.paypal_order_id)) throw new Error('Purchase not found');
  if (row.status !== 'fulfilled') {
    try { await paypal.captureOrder(row.paypal_order_id, purchaseId); }
    catch {
      // A previous capture can have succeeded despite a timeout or lost response.
      // Only the authenticated PayPal order lookup below can establish success.
    }
  }
  const order = await paypal.getOrder(row.paypal_order_id);
  return fulfillVerifiedPurchase(db, secret, { purchaseId, discordId, merchantId, order });
}
